    expect: [200, 503], // Health should work without auth
  });

  // ─── DB AUDIT ──────────────────────────────────────────────
  header("10. DATABASE STATE");

  const tables = ["tasks", "agents", "bids", "chunks", "verification_jobs", "activity_log"];
  for (const t of tables) {
