  }

  await pool.end();

  // ─── REPORT ────────────────────────────────────────────────
  console.log(`\n\n${"═".repeat(70)}`);
  console.log("  📋 FULL API TEST REPORT");
  console.log(`${"═".repeat(70)}\n`);

  for (const r of results) {
    const ep = r.endpoint.padEnd(40);
    const st = r.status.padEnd(10);
    const ms = r.ms > 0 ? `${String(r.ms).padStart(5)}ms` : "      ";
    const det = r.detail ? `  ${r.detail.slice(0, 45)}` : "";
    console.log(`  ${st} ${ep} ${ms}${det}`);
  }

  console.log(`\n${"─".repeat(70)}`);
  console.log(`  ✅ Passed: ${passed}    ❌ Failed: ${failed}    Total: ${results.length}`);
  console.log(`  Pass rate: ${((passed / (passed + failed)) * 100).toFixed(1)}%`);
  console.log(`${"═".repeat(70)}`);

  if (failed > 0) {
    console.log("\n  ⚠️  FAILURES detected — review above");
    process.exit(1);
  } else {
    console.log("\n  🎉 ALL TESTS PASSED!");
  }
}

main().catch((err) => { console.error("💥 Suite crashed:", err.message); process.exit(1); });

/**
 * Synthetic local-chain dispute drill.
 *
 * Exercises the real wallet → TaskManager → DisputeResolution → EscrowVault
 * path plus the API's receipt projection. It uses only Hardhat accounts and
 * deletes its PostgreSQL projection when complete; no external dispute or
 * institutional decision is represented.
 */
import { createHash, randomUUID } from "node:crypto";
import { Pool } from "pg";
import {
  createPublicClient,
  createWalletClient,
  decodeEventLog,
  defineChain,
  http,
  keccak256,
  parseEther,
  toHex,
  type Address,
} from "viem";

const apiBase = process.env.API_BASE || "http://localhost:3001/api/v1";
const rpcUrl = process.env.RPC_URL || "http://127.0.0.1:8545";
const chainId = Number(process.env.CHAIN_ID || 31337);
const databaseUrl = process.env.DATABASE_URL
  || "postgres://aiwork:aiwork_secret_change_me@localhost:5432/aiwork";
const addresses = {
  token: process.env.TOKEN_ADDRESS,
  registry: process.env.AGENT_REGISTRY_ADDRESS,
  escrow: process.env.ESCROW_VAULT_ADDRESS,
  taskManager: process.env.TASK_MANAGER_ADDRESS,
  disputes: process.env.DISPUTE_RESOLUTION_ADDRESS,
};

for (const [name, value] of Object.entries(addresses)) {
  if (!/^0x[0-9a-fA-F]{40}$/.test(value || "")) throw new Error(`${name} address is required`);
}

async function artifact(relativePath: string) {
  return Bun.file(new URL(`../../artifacts/contracts/${relativePath}`, import.meta.url)).json();
}

async function walletHeaders(path: string, method: string, body: string, signer: any) {
  const address = signer.account.address;
  const message = [
    "AIWork request v2",
    "origin:http://localhost:5173",
    `chainId:${chainId}`,
    `method:${method}`,
    `path:${path}`,
    `bodySha256:${createHash("sha256").update(body).digest("hex")}`,
    `issuedAt:${new Date().toISOString()}`,
    `nonce:${randomUUID()}`,
  ].join("\n");
  return {
    "Content-Type": "application/json",
    "X-Wallet-Address": address,
    "X-Wallet-Message": Buffer.from(message).toString("base64url"),
    "X-Wallet-Signature": await signer.signMessage({ message }),
  };
}

async function expectJson(response: Response, context: string) {
  const value: any = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(`${context}: ${response.status} ${value.error || JSON.stringify(value)}`);
  return value;
}

const chain = defineChain({
  id: chainId,
  name: "AIWork synthetic drill chain",
  nativeCurrency: { name: "Ether", symbol: "ETH", decimals: 18 },
  rpcUrls: { default: { http: [rpcUrl] } },
});
const transport = http(rpcUrl);
const publicClient = createPublicClient({ chain, transport });
const accountSource = createWalletClient({ chain, transport });
const db = new Pool({ connectionString: databaseUrl });
let taskId: string | undefined;
let agentId: string | undefined;
let insertedAgent = false;

try {
  const rpcAccounts = await accountSource.getAddresses();
  const signer = (index: number) => createWalletClient({ account: rpcAccounts[index]!, chain, transport });
  const [deployer, worker, poster, arbiter1, arbiter2] = [signer(0), signer(1), signer(7), signer(4), signer(5)];
  const [tokenArtifact, registryArtifact, escrowArtifact, taskArtifact, disputeArtifact] = await Promise.all([
    artifact("AIWorkToken.sol/AIWorkToken.json"),
    artifact("AgentRegistry.sol/AgentRegistry.json"),
    artifact("EscrowVault.sol/EscrowVault.json"),
    artifact("TaskManager.sol/TaskManager.json"),
    artifact("DisputeResolution.sol/DisputeResolution.json"),
  ]);
  const tokenAddress = addresses.token as Address;
  const registryAddress = addresses.registry as Address;
  const escrowAddress = addresses.escrow as Address;
  const taskManagerAddress = addresses.taskManager as Address;
  const disputeAddress = addresses.disputes as Address;
  const workerAddress = worker.account.address;
  const posterAddress = poster.account.address;
  const send = async (client: any, address: Address, abi: any, functionName: string, args: any[] = []) => {
    const hash = await client.writeContract({ address, abi, functionName, args });
    return publicClient.waitForTransactionReceipt({ hash });
  };

  agentId = await publicClient.readContract({
    address: registryAddress, abi: registryArtifact.abi,
    functionName: "addressToAgentId", args: [workerAddress],
  }) as string;
  if (!agentId) {
    await send(deployer, registryAddress, registryArtifact.abi, "registerAgent", [
      workerAddress, workerAddress, 2, ["synthetic-dispute-drill"],
    ]);
    agentId = await publicClient.readContract({
      address: registryAddress, abi: registryArtifact.abi,
      functionName: "addressToAgentId", args: [workerAddress],
    }) as string;
  }
  const profile: any = await publicClient.readContract({
    address: registryAddress, abi: registryArtifact.abi,
    functionName: "getAgent", args: [agentId],
  });
  if (Number(profile.status) === 0) await send(deployer, registryAddress, registryArtifact.abi, "activateAgent", [agentId]);

  const reward = parseEther("100");
  const bond = await publicClient.readContract({
    address: disputeAddress, abi: disputeArtifact.abi, functionName: "disputeBond",
  }) as bigint;
  await send(deployer, tokenAddress, tokenArtifact.abi, "transfer", [posterAddress, reward + bond + parseEther("10")]);
  await send(poster, tokenAddress, tokenArtifact.abi, "approve", [escrowAddress, reward]);
  await send(poster, tokenAddress, tokenArtifact.abi, "approve", [disputeAddress, bond]);

  const deadline = Math.floor(Date.now() / 1000) + 3600;
  const postReceipt = await send(poster, taskManagerAddress, taskArtifact.abi, "postTask", [
    `Synthetic dispute drill ${randomUUID()}`,
    "CODE",
    0,
    tokenAddress,
    reward,
    0,
    1,
    deadline,
    keccak256(toHex("synthetic requirements")),
    [],
    [],
  ]);
  const posted = postReceipt.logs
    .filter((log) => log.address.toLowerCase() === taskManagerAddress.toLowerCase())
    .map((log) => { try { return decodeEventLog({ abi: taskArtifact.abi, data: log.data, topics: log.topics }); } catch { return null; } })
    .find((event: any) => event?.eventName === "TaskPosted") as any;
  taskId = posted?.args?.taskId as string | undefined;
  if (!taskId) throw new Error("TaskPosted event missing");
  await send(deployer, taskManagerAddress, taskArtifact.abi, "assignTask", [taskId, agentId]);

  const existingAgent = await db.query("SELECT 1 FROM agents WHERE agent_id = $1", [agentId]);
  insertedAgent = !existingAgent.rowCount;
  await db.query(
    `INSERT INTO agents (agent_id, wallet_address, payment_address, category, status, skills)
     VALUES ($1,$2,$2,'CODE','ACTIVE',$3)
     ON CONFLICT (agent_id) DO UPDATE SET wallet_address = EXCLUDED.wallet_address,
       payment_address = EXCLUDED.payment_address, status = 'ACTIVE'`,
    [agentId, workerAddress, ["synthetic-dispute-drill"]],
  );
  await db.query(
    `INSERT INTO tasks (task_id, employer, worker_agent, title, category, phase, max_budget, deadline)
     VALUES ($1,$2,$3,'Synthetic dispute drill','CODE','IN_PROGRESS',100,to_timestamp($4))`,
    [taskId, posterAddress, agentId, deadline],
  );

  const reason = "Synthetic disagreement for atomic-settlement drill";
  const openReceipt = await send(poster, taskManagerAddress, taskArtifact.abi, "openDispute", [
    taskId, keccak256(toHex(reason)),
  ]);
  const projectionBody = JSON.stringify({ taskId, reason, openTxHash: openReceipt.transactionHash });
  const projection = await expectJson(await fetch(`${apiBase}/disputes`, {
    method: "POST",
    headers: await walletHeaders("/api/v1/disputes", "POST", projectionBody, poster),
    body: projectionBody,
  }), "project dispute");
  const chainDisputeId = BigInt(projection.dispute.chain_dispute_id);
  const indexedId = projection.dispute.id;

  await send(arbiter1, disputeAddress, disputeArtifact.abi, "vote", [chainDisputeId, 1]);
  const resolutionReceipt = await send(arbiter2, disputeAddress, disputeArtifact.abi, "vote", [chainDisputeId, 1]);
  const syncBody = JSON.stringify({ txHash: resolutionReceipt.transactionHash });
  const synced = await expectJson(await fetch(`${apiBase}/disputes/${indexedId}/sync`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: syncBody,
  }), "sync dispute");

  const [task, escrowState, indexed] = await Promise.all([
    publicClient.readContract({ address: taskManagerAddress, abi: taskArtifact.abi, functionName: "tasks", args: [taskId] }),
    publicClient.readContract({ address: escrowAddress, abi: escrowArtifact.abi, functionName: "getEscrow", args: [taskId] }),
    db.query("SELECT status, resolution, settlement_status, settlement_tx_hash FROM disputes WHERE id = $1", [indexedId]),
  ]);
  const taskStatus = (task as any).status ?? (task as any)[6];
  const escrowActive = (escrowState as any).isActive ?? (escrowState as any)[7];
  const escrowReleased = (escrowState as any).released ?? (escrowState as any)[4];
  if (Number(taskStatus) !== 4) throw new Error(`Expected COMPLETED task, got status ${taskStatus}`);
  if (escrowActive || escrowReleased !== reward) throw new Error("Escrow was not fully and atomically settled");
  const row = indexed.rows[0];
  if (synced.dispute.settlement_status !== "SETTLED" || row?.resolution !== "FAVOR_WORKER"
      || row?.settlement_tx_hash?.toLowerCase() !== resolutionReceipt.transactionHash.toLowerCase()) {
    throw new Error("Database projection does not match the finalized chain settlement");
  }

  console.log("PASS synthetic dispute API drill: wallet open → panel → 2/3 vote → atomic settlement → receipt sync");
} finally {
  if (taskId) {
    await db.query("DELETE FROM disputes WHERE task_id = $1", [taskId]).catch(() => {});
    await db.query("DELETE FROM tasks WHERE task_id = $1", [taskId]).catch(() => {});
  }
  if (insertedAgent && agentId) await db.query("DELETE FROM agents WHERE agent_id = $1", [agentId]).catch(() => {});
  await db.end();
}

# Independent security assessment scope

This is a procurement-ready scope, not an audit report. Assessors must be independent, name their methods and limitations, and test the pinned release commit and deployed bytecode.

## Required workstreams

### 1. Smart contracts

Assess `AgentRegistry`, `TaskManager`, `EscrowVault`, `DisputeResolution`, `BiddingEngine`, `ComplexityOracle`, token interactions, deployment scripts, and the complete role graph. Prioritize:

- escrow conservation across every state transition;
- reentrancy and adversarial ERC-20 behavior, including fee-on-transfer and callback tokens;
- integer rounding, milestone percentages, bonuses, cancellation, timeouts, and double release;
- role escalation, upgrade or replacement authority, verifier round replay, equivocation, and quorum reset;
- dispute bond accounting, party exclusion, panel replacement, early majority, and atomic settlement;
- chain reorganization assumptions and API/database crash windows.

Deliver manual review, static analysis, property and invariant tests, attack proofs for findings, and deployed-bytecode comparison.

### 2. API, identity, and web application

Assess against the pinned [OWASP ASVS 5.0](https://owasp.org/www-project-application-security-verification-standard/) requirement identifiers. Cover wallet-message origin/method/path/body binding, nonce consumption, API-key scope, IDOR, role resolution, institutional-record authorization, SQL injection, SSRF, stored and reflected script injection, request limits, CORS, CSP, secrets, audit integrity, and rate-limit distribution.

### 3. Sandbox and supply chain

Attempt repository-to-host escape, credential theft, metadata-service access, unrestricted egress, dependency confusion, resource exhaustion, verifier-result forgery, commit substitution, and cross-job data access. Verify pinned images, signatures, SBOMs, provenance, secret separation, and the production refusal of simulated verification.

### 4. Protocol abuse

Model verifier and arbiter collusion, identity-cluster Sybils, review rings, bribery, griefing, withheld votes, malicious funders, malicious builders, webhook replay, and evidence-graph poisoning. Record which failures are prevented, detected, recoverable, or accepted.

## Deliverables

- executive report with explicit scope and exclusions;
- technical findings with severity, exploitability, affected commit, proof, and remediation;
- contract invariants and test artifacts contributed under an agreed license;
- ASVS matrix using versioned requirement identifiers;
- sandbox penetration-test evidence and egress map;
- retest letter that lists closed, open, and risk-accepted findings;
- report digest and assessor signature.

## Acceptance gate

Mainnet remains blocked until two independent contract assessors complete retesting, every Critical and High issue is closed, and every remaining issue has a named owner, deadline, and signed risk decision. An application or sandbox assessment cannot substitute for a contract audit, and one vendor cannot count as two independent assessors.

The secure-development evidence package should also map repository practices to [NIST SP 800-218](https://csrc.nist.gov/pubs/sp/800/218/final), including protected environments, dependency provenance, vulnerability response, and retention of release evidence.

# Production hardening overlay.
#
# Every externally sourced image is supplied as an immutable digest reference,
# for example `postgres:18-alpine@sha256:...`. Compose fails before deployment
# when a required secret, signer, verifier target, or image lock is absent.

x-worker-build: &worker-build
  build:
    context: .
    dockerfile: docker/Dockerfile.api
  restart: unless-stopped
  depends_on:
    postgres:
      condition: service_healthy

x-worker-environment: &worker-environment
  NODE_ENV: production
  DATABASE_URL: postgres://aiwork:${POSTGRES_PASSWORD:?required}@postgres:5432/aiwork
  RPC_URL: ${RPC_URL:?required}
  CHAIN_ID: ${CHAIN_ID:?required}
  TOKEN_ADDRESS: ${TOKEN_ADDRESS:?required}
  AGENT_REGISTRY_ADDRESS: ${AGENT_REGISTRY_ADDRESS:?required}
  ESCROW_VAULT_ADDRESS: ${ESCROW_VAULT_ADDRESS:?required}
  COMPLEXITY_ORACLE_ADDRESS: ${COMPLEXITY_ORACLE_ADDRESS:?required}
  TASK_MANAGER_ADDRESS: ${TASK_MANAGER_ADDRESS:?required}
  BIDDING_ENGINE_ADDRESS: ${BIDDING_ENGINE_ADDRESS:?required}
  DISPUTE_RESOLUTION_ADDRESS: ${DISPUTE_RESOLUTION_ADDRESS:?required}
  OTEL_EXPORTER_OTLP_ENDPOINT: http://signoz-otel-collector:4318
  OTEL_SERVICE_VERSION: ${RELEASE_VERSION:?required}

services:
  postgres:
    image: ${POSTGRES_IMAGE:?set an immutable digest-pinned PostgreSQL image}
    environment:
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD:?required}

  forgejo:
    image: ${FORGEJO_IMAGE:?set an immutable digest-pinned Forgejo image}
    environment:
      FORGEJO__database__PASSWD: ${POSTGRES_PASSWORD:?required}

  daytona-api:
    image: ${DAYTONA_API_IMAGE:?set an immutable digest-pinned Daytona API image}
    environment:
      ENCRYPTION_KEY: ${DAYTONA_ENCRYPTION_KEY:?required}
      ENCRYPTION_SALT: ${DAYTONA_ENCRYPTION_SALT:?required}
      DB_PASSWORD: ${DAYTONA_DB_PASSWORD:?required}
      TRANSIENT_REGISTRY_PASSWORD: ${DAYTONA_REGISTRY_PASSWORD:?required}
      INTERNAL_REGISTRY_PASSWORD: ${DAYTONA_REGISTRY_PASSWORD:?required}
      S3_ACCESS_KEY: ${DAYTONA_S3_ACCESS_KEY:?required}
      S3_SECRET_KEY: ${DAYTONA_S3_SECRET_KEY:?required}
      PROXY_API_KEY: ${DAYTONA_PROXY_API_KEY:?required}
      DEFAULT_RUNNER_API_KEY: ${DAYTONA_RUNNER_API_KEY:?required}
      OIDC_ISSUER_BASE_URL: ${DAYTONA_OIDC_ISSUER:?required}
      PUBLIC_OIDC_DOMAIN: ${DAYTONA_PUBLIC_OIDC_DOMAIN:?required}
      DASHBOARD_URL: ${DAYTONA_DASHBOARD_URL:?required}
      DASHBOARD_BASE_API_URL: ${DAYTONA_DASHBOARD_URL:?required}
      SKIP_USER_EMAIL_VERIFICATION: "false"
    privileged: false

  daytona-runner:
    image: ${DAYTONA_RUNNER_IMAGE:?set an immutable digest-pinned Daytona runner image}
    environment:
      DAYTONA_RUNNER_TOKEN: ${DAYTONA_RUNNER_API_KEY:?required}
      AWS_ACCESS_KEY_ID: ${DAYTONA_S3_ACCESS_KEY:?required}
      AWS_SECRET_ACCESS_KEY: ${DAYTONA_S3_SECRET_KEY:?required}
      ENVIRONMENT: production
      INTER_SANDBOX_NETWORK_ENABLED: "false"
      SSH_GATEWAY_ENABLE: "false"

  daytona-db:
    image: ${POSTGRES_IMAGE:?set an immutable digest-pinned PostgreSQL image}
    environment:
      POSTGRES_PASSWORD: ${DAYTONA_DB_PASSWORD:?required}

  daytona-redis:
    image: ${REDIS_IMAGE:?set an immutable digest-pinned Redis image}

  daytona-dex:
    image: ${DEX_IMAGE:?set an immutable digest-pinned Dex image}
    volumes:
      - type: bind
        source: ${DAYTONA_DEX_CONFIG_PATH:?provide a production Dex config without local credentials}
        target: /etc/dex/config.yaml
        read_only: true

  daytona-minio:
    image: ${MINIO_IMAGE:?set an immutable digest-pinned MinIO image}
    environment:
      MINIO_ROOT_USER: ${DAYTONA_S3_ACCESS_KEY:?required}
      MINIO_ROOT_PASSWORD: ${DAYTONA_S3_SECRET_KEY:?required}

  daytona-registry:
    image: ${REGISTRY_IMAGE:?set an immutable digest-pinned OCI registry image}

  api:
    image: ${AIWORK_API_IMAGE:?set the immutable digest-pinned API image}
    environment:
      NODE_ENV: production
      DATABASE_URL: postgres://aiwork:${POSTGRES_PASSWORD:?required}@postgres:5432/aiwork
      PLATFORM_PRIVATE_KEY: ${PLATFORM_PRIVATE_KEY:?required}
      DAYTONA_API_KEY: ${DAYTONA_API_KEY:?required}
      FORGEJO_ADMIN_TOKEN: ${FORGEJO_ADMIN_TOKEN:?required}
      FORGEJO_READ_TOKEN: ${FORGEJO_READ_TOKEN:?required}
      FORGEJO_WEBHOOK_SECRET: ${WEBHOOK_SECRET:?required}
      API_KEYS: ${API_KEYS:?required}
      ALLOWED_ORIGINS: ${ALLOWED_ORIGINS:?required}
      AUTH_ALLOWED_ORIGINS: ${AUTH_ALLOWED_ORIGINS:?required}
      RPC_URL: ${RPC_URL:?required}
      CHAIN_ID: ${CHAIN_ID:?required}
      TOKEN_ADDRESS: ${TOKEN_ADDRESS:?required}
      AGENT_REGISTRY_ADDRESS: ${AGENT_REGISTRY_ADDRESS:?required}
      ESCROW_VAULT_ADDRESS: ${ESCROW_VAULT_ADDRESS:?required}
      COMPLEXITY_ORACLE_ADDRESS: ${COMPLEXITY_ORACLE_ADDRESS:?required}
      TASK_MANAGER_ADDRESS: ${TASK_MANAGER_ADDRESS:?required}
      BIDDING_ENGINE_ADDRESS: ${BIDDING_ENGINE_ADDRESS:?required}
      DISPUTE_RESOLUTION_ADDRESS: ${DISPUTE_RESOLUTION_ADDRESS:?required}
      VERIFIER_QUORUM: ${VERIFIER_QUORUM:?required}
      VERIFIER_INSTANCE_IDS: verifier-1,verifier-2,verifier-3
      ARBITER_ADDRESSES: ${ARBITER_ADDRESSES:?required}
      WORKER_QUEUES: ""
      OTEL_SERVICE_VERSION: ${RELEASE_VERSION:?required}
    deploy:
      replicas: 2
      update_config:
        order: start-first
        failure_action: rollback
      rollback_config:
        order: stop-first

  scheduler:
    <<: *worker-build
    image: ${AIWORK_API_IMAGE:?set the immutable digest-pinned API image}
    command: ["bun", "run", "src/worker.ts"]
    environment:
      <<: *worker-environment
      PLATFORM_PRIVATE_KEY: ${PLATFORM_PRIVATE_KEY:?required}
      WORKER_QUEUES: bidding-deadline,notifications
      OTEL_SERVICE_NAME: aiwork-scheduler

  verifier-1:
    <<: *worker-build
    image: ${AIWORK_API_IMAGE:?set the immutable digest-pinned API image}
    command: ["bun", "run", "src/worker.ts"]
    environment:
      <<: *worker-environment
      PLATFORM_PRIVATE_KEY: ${VERIFIER_1_PRIVATE_KEY:?required}
      VERIFIER_INSTANCE_ID: verifier-1
      WORKER_QUEUES: verification
      DAYTONA_API_URL: ${VERIFIER_1_DAYTONA_API_URL:?required}
      DAYTONA_API_KEY: ${VERIFIER_1_DAYTONA_API_KEY:?required}
      FORGEJO_READ_TOKEN: ${VERIFIER_1_FORGEJO_READ_TOKEN:?required}
      OTEL_SERVICE_NAME: aiwork-verifier-1

  verifier-2:
    <<: *worker-build
    image: ${AIWORK_API_IMAGE:?set the immutable digest-pinned API image}
    command: ["bun", "run", "src/worker.ts"]
    environment:
      <<: *worker-environment
      PLATFORM_PRIVATE_KEY: ${VERIFIER_2_PRIVATE_KEY:?required}
      VERIFIER_INSTANCE_ID: verifier-2
      WORKER_QUEUES: verification
      DAYTONA_API_URL: ${VERIFIER_2_DAYTONA_API_URL:?required}
      DAYTONA_API_KEY: ${VERIFIER_2_DAYTONA_API_KEY:?required}
      FORGEJO_READ_TOKEN: ${VERIFIER_2_FORGEJO_READ_TOKEN:?required}
      OTEL_SERVICE_NAME: aiwork-verifier-2

  verifier-3:
    <<: *worker-build
    image: ${AIWORK_API_IMAGE:?set the immutable digest-pinned API image}
    command: ["bun", "run", "src/worker.ts"]
    environment:
      <<: *worker-environment
      PLATFORM_PRIVATE_KEY: ${VERIFIER_3_PRIVATE_KEY:?required}
      VERIFIER_INSTANCE_ID: verifier-3
      WORKER_QUEUES: verification
      DAYTONA_API_URL: ${VERIFIER_3_DAYTONA_API_URL:?required}
      DAYTONA_API_KEY: ${VERIFIER_3_DAYTONA_API_KEY:?required}
      FORGEJO_READ_TOKEN: ${VERIFIER_3_FORGEJO_READ_TOKEN:?required}
      OTEL_SERVICE_NAME: aiwork-verifier-3

  frontend:
    image: ${AIWORK_FRONTEND_IMAGE:?set the immutable digest-pinned frontend image}

  caddy:
    image: ${CADDY_IMAGE:?set an immutable digest-pinned Caddy image}
    environment:
      SITE_ADDRESS: ${SITE_ADDRESS:?required}
      API_ADDRESS: ${API_ADDRESS:?required}
      GIT_ADDRESS: ${GIT_ADDRESS:?required}

  signoz-zookeeper:
    image: ${ZOOKEEPER_IMAGE:?set an immutable digest-pinned Zookeeper image}

  signoz-init-clickhouse:
    image: ${CLICKHOUSE_IMAGE:?set an immutable digest-pinned ClickHouse image}

  signoz-clickhouse:
    image: ${CLICKHOUSE_IMAGE:?set an immutable digest-pinned ClickHouse image}

  signoz-telemetry-migrator:
    image: ${SIGNOZ_OTEL_IMAGE:?set an immutable digest-pinned SigNoz collector image}

  signoz:
    image: ${SIGNOZ_IMAGE:?set an immutable digest-pinned SigNoz image}
    environment:
      SIGNOZ_TOKENIZER_JWT_SECRET: ${SIGNOZ_JWT_SECRET:?required}

  signoz-otel-collector:
    image: ${SIGNOZ_OTEL_IMAGE:?set an immutable digest-pinned SigNoz collector image}

